package com.pratik.imagetap;
import android.app.*;import android.content.*;import android.provider.Settings;import android.view.*;import android.widget.*;import java.util.function.Consumer;
final class AutoTapUi {
 static void add(LinearLayout box,View v){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=Ui.dp(box.getContext(),12);box.addView(v,lp);}
 static Button button(Context c,LinearLayout box,String name,Runnable click){Button b=Ui.button(c,name,false);add(box,b);b.setOnClickListener(v->click.run());return b;}
 static void page(Activity a,LinearLayout body,Runnable refresh){
  add(body,Ui.label(a,"AUTO TAP",11,Ui.GREEN));add(body,Ui.label(a,"Place. Play. Repeat.",30,Ui.CREAM));add(body,Ui.label(a,"A dedicated clicker with numbered targets. No image detection needed.",14,Ui.MUTED));
  AutoTapPlan plan;try{plan=AutoTapStore.load(a);}catch(RuntimeException e){add(body,Ui.label(a,e.getMessage(),14,Ui.RED));button(a,body,"Reset Auto Tap layout",()->{AutoTapStore.save(a,new AutoTapPlan());refresh.run();});return;}
  LinearLayout card=Ui.column(a);card.setPadding(Ui.dp(a,18),Ui.dp(a,18),Ui.dp(a,18),Ui.dp(a,18));card.setBackground(Ui.shape(a,Ui.SURFACE,Ui.LINE,20));add(body,card);add(card,Ui.label(a,plan.points.size()+(plan.points.size()==1?" numbered target":" numbered targets"),22,Ui.CREAM));add(card,Ui.label(a,"Default hold "+plan.hold+" ms · gap "+plan.gap+" ms\n"+(plan.cycles==0?"Continuous":plan.cycles+" cycles")+" · targets run 1 → 2 → …",13,Ui.MUTED));
  Switch allow=new ActiveSwitch(a);allow.setText("Allow actions");allow.setChecked(a.getSharedPreferences("config",0).getBoolean("tap",false));Ui.polish(allow);add(body,allow);allow.setOnCheckedChangeListener((v,on)->a.getSharedPreferences("config",0).edit().putBoolean("tap",on).apply());
  button(a,body,"Open Auto Tap controls",()->launch(a,false));button(a,body,"Number of targets",()->count(a,plan,p->changed(a,p,refresh)));button(a,body,"Speed & run limits",()->settings(a,plan,p->changed(a,p,refresh)));button(a,body,"Saved layouts · 3 slots",()->profiles(a,plan,p->changed(a,p,refresh)));button(a,body,"Test taps on this phone",()->launch(a,true));
  add(body,Ui.label(a,"Drag each numbered circle while paused. Tap a circle for exact coordinates and individual timing. Play hides the circles so they cannot intercept taps.\n\nFastest uses a 1 ms hold with no added gap. Actual speed depends on your phone and the receiving app; increase hold time if taps are missed. The popup reports completed gestures, while the test screen counts received taps.",13,Ui.MUTED));
 }
 static void changed(Context c,AutoTapPlan p,Runnable refresh){AutoTapStore.save(c,p);if(TapService.instance!=null)TapService.instance.reloadAutoTap();refresh.run();}
 static void launch(Activity a,boolean test){TapService s=TapService.instance;if(s==null){new AlertDialog.Builder(a).setTitle("Enable AutoBash accessibility").setMessage("Auto Tap needs Accessibility access to place controls and send taps.").setPositiveButton("Open settings",(d,w)->a.startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS))).setNegativeButton("Cancel",null).show();return;}if(!s.openAutoTap(false))return;if(test)a.startActivity(new Intent(a,TapTestActivity.class));else{String pkg=a.getSharedPreferences("config",0).getString("app","");Intent launch=pkg.isEmpty()?null:a.getPackageManager().getLaunchIntentForPackage(pkg);a.startActivity(launch!=null?launch:new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME));}}
 static LinearLayout form(Context c){LinearLayout box=Ui.column(c);box.setPadding(Ui.dp(c,20),Ui.dp(c,12),Ui.dp(c,20),Ui.dp(c,8));return box;}
 static EditText number(Context c,LinearLayout box,String label,String value){add(box,Ui.label(c,label,13,Ui.CREAM));EditText e=new EditText(c);e.setSingleLine(true);e.setTextColor(Ui.CREAM);e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL|android.text.InputType.TYPE_NUMBER_FLAG_SIGNED);e.setText(value);e.setContentDescription(label);add(box,e);return e;}
 static AlertDialog dialog(Context c,String title,View content,String ok,Runnable save){if(content instanceof LinearLayout)HelpGuide.button(c,(LinearLayout)content,HelpGuide.topic(title));if(content instanceof LinearLayout)HelpGuide.button(c,(LinearLayout)content,HelpGuide.topic(title));if(content instanceof LinearLayout)HelpGuide.button(c,(LinearLayout)content,HelpGuide.topic(title));ScrollView scroll=new ScrollView(c);scroll.addView(content);AlertDialog d=new AlertDialog.Builder(c).setTitle(title).setView(scroll).setNegativeButton("Cancel",null).setPositiveButton(ok,null).create();if(!(c instanceof Activity))d.getWindow().setType(WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY);d.show();d.getButton(-1).setOnClickListener(b->{try{save.run();d.dismiss();}catch(RuntimeException e){Toast.makeText(c,e.getMessage()==null?"Enter valid numbers":e.getMessage(),Toast.LENGTH_LONG).show();}});if(c instanceof TapService)((TapService)c).autoTapDialog(d);return d;}
 static void count(Context c,AutoTapPlan original,Consumer<AutoTapPlan> saved){LinearLayout box=form(c);NumberPicker n=new NumberPicker(c);n.setMinValue(1);n.setMaxValue(AutoTapPlan.MAX_TARGETS);n.setValue(original.points.size());n.setWrapSelectorWheel(false);n.setContentDescription("Number of tap targets");add(box,n);add(box,Ui.label(c,"Changing the layout starts a new run. Reducing the count removes the last targets.",12,Ui.MUTED));dialog(c,"Number of targets",box,"Apply",()->{AutoTapPlan p=AutoTapPlan.decode(original.encode());n.clearFocus();p.count(n.getValue());saved.accept(p);});}
 static void settings(Context c,AutoTapPlan original,Consumer<AutoTapPlan> saved){LinearLayout box=form(c);EditText hold=number(c,box,"Hold time · 1–1000 ms",""+original.hold),gap=number(c,box,"Gap after completion · 0–60000 ms",""+original.gap),delay=number(c,box,"Start delay · 0–60000 ms",""+original.startDelay),cycles=number(c,box,"Cycle limit · 0 means continuous",""+original.cycles);boolean[] clear={false};button(c,box,"Fastest · 1 ms hold / 0 ms gap",()->{hold.setText("1");gap.setText("0");clear[0]=true;});button(c,box,"Reliable · 100 ms hold / 100 ms gap",()->{hold.setText("100");gap.setText("100");clear[0]=true;});add(box,Ui.label(c,"Speed presets reset individual timing overrides. Saving settings starts a new run. A cycle visits every target once.",12,Ui.MUTED));dialog(c,"Speed & run limits",box,"Save",()->{AutoTapPlan p=AutoTapPlan.decode(original.encode());p.hold=Integer.parseInt(hold.getText().toString());p.gap=Integer.parseInt(gap.getText().toString());p.startDelay=Integer.parseInt(delay.getText().toString());p.cycles=Integer.parseInt(cycles.getText().toString());if(clear[0])for(AutoTapPlan.Point q:p.points){q.hold=0;q.gap=-1;}p.validate();saved.accept(p);});}
 static void point(Context c,AutoTapPlan original,int index,Consumer<AutoTapPlan> saved){AutoTapPlan.Point q=original.points.get(index);LinearLayout box=form(c);EditText x=number(c,box,"X · screen percentage",String.format(java.util.Locale.US,"%.2f",q.x*100)),y=number(c,box,"Y · screen percentage",String.format(java.util.Locale.US,"%.2f",q.y*100)),hold=number(c,box,"Hold override · 0 uses default",""+q.hold),gap=number(c,box,"Gap override · −1 uses default",""+q.gap);dialog(c,"Target "+(index+1),box,"Save",()->{AutoTapPlan p=AutoTapPlan.decode(original.encode());AutoTapPlan.Point item=p.points.get(index);item.x=Float.parseFloat(x.getText().toString())/100;item.y=Float.parseFloat(y.getText().toString())/100;item.hold=Integer.parseInt(hold.getText().toString());item.gap=Integer.parseInt(gap.getText().toString());p.validate();saved.accept(p);});}
 static void profiles(Context c,AutoTapPlan plan,Consumer<AutoTapPlan> saved){LinearLayout box=form(c);final AlertDialog[] outer={null};for(int i=0;i<3;i++){final int slot=i;String name=AutoTapStore.prefs(c).getString("name"+i,"Empty slot "+(i+1));add(box,Ui.label(c,name,18,Ui.CREAM));button(c,box,"Save to slot "+(i+1),()->{LinearLayout form=form(c);EditText title=new EditText(c);title.setSingleLine(true);title.setText(AutoTapStore.prefs(c).getString("name"+slot,"Layout "+(slot+1)));title.setContentDescription("Layout name");add(form,title);dialog(c,"Name this layout",form,"Save",()->{AutoTapStore.slot(c,slot,title.getText().toString(),plan);if(outer[0]!=null)outer[0].dismiss();});});Button load=button(c,box,"Load slot "+(i+1),()->{saved.accept(AutoTapStore.slot(c,slot));if(outer[0]!=null)outer[0].dismiss();});load.setEnabled(AutoTapStore.prefs(c).contains("slot"+slot));}outer[0]=dialog(c,"Saved layouts",box,"Close",()->{});}
}
